package net.minecraft.core.registries;import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.Item;public class BuiltInRegistries{public static Registry ITEM=new Registry(),ENTITY_TYPE=new Registry();public static class Registry{public Map<String,Item> items=new HashMap<>();public void put(String id){items.put(id,new Item(id));}public Object get(ResourceLocation id){return items.getOrDefault(id.value(),items.get("minecraft:air"));}public boolean containsKey(ResourceLocation id){return items.containsKey(id.value());}public ResourceLocation getKey(Object item){return ResourceLocation.parse(item instanceof Item i?i.id:((fixture.Game.Type)item).id());}}}
